module axis_async_fifo #
(
    parameter DEPTH = 4096,
    parameter DATA_WIDTH = 8,
    parameter KEEP_ENABLE = (DATA_WIDTH>8),
    parameter KEEP_WIDTH = ((DATA_WIDTH+7)/8),
    parameter LAST_ENABLE = 1,
    parameter ID_ENABLE = 0,
    parameter ID_WIDTH = 8,
    parameter DEST_ENABLE = 0,
    parameter DEST_WIDTH = 8,
    parameter USER_ENABLE = 1,
    parameter USER_WIDTH = 1,
    parameter RAM_PIPELINE = 1,
    parameter OUTPUT_FIFO_ENABLE = 0,
    parameter FRAME_FIFO = 0,
    parameter USER_BAD_FRAME_VALUE = 1'b1,
    parameter USER_BAD_FRAME_MASK = 1'b1,
    parameter DROP_OVERSIZE_FRAME = FRAME_FIFO,
    parameter DROP_BAD_FRAME = 0,
    parameter DROP_WHEN_FULL = 0,
    parameter MARK_WHEN_FULL = 0,
    parameter PAUSE_ENABLE = 0,
    parameter FRAME_PAUSE = FRAME_FIFO
)
(
    /*
     * AXI input
     */
    input  wire                   s_clk,
    input  wire                   s_rst,
    input  wire [DATA_WIDTH-1:0]  s_axis_tdata,
    input  wire [KEEP_WIDTH-1:0]  s_axis_tkeep,
    input  wire                   s_axis_tvalid,
    output wire                   s_axis_tready,
    input  wire                   s_axis_tlast,
    input  wire [ID_WIDTH-1:0]    s_axis_tid,
    input  wire [DEST_WIDTH-1:0]  s_axis_tdest,
    input  wire [USER_WIDTH-1:0]  s_axis_tuser,
    /*
     * AXI output
     */
    input  wire                   m_clk,
    input  wire                   m_rst,
    output wire [DATA_WIDTH-1:0]  m_axis_tdata,
    output wire [KEEP_WIDTH-1:0]  m_axis_tkeep,
    output wire                   m_axis_tvalid,
    input  wire                   m_axis_tready,
    output wire                   m_axis_tlast,
    output wire [ID_WIDTH-1:0]    m_axis_tid,
    output wire [DEST_WIDTH-1:0]  m_axis_tdest,
    output wire [USER_WIDTH-1:0]  m_axis_tuser,
    /*
     * Pause
     */
    input  wire                   s_pause_req,
    output wire                   s_pause_ack,
    input  wire                   m_pause_req,
    output wire                   m_pause_ack,
    /*
     * Status
     */
    output wire [$clog2(DEPTH):0] s_status_depth,
    output wire [$clog2(DEPTH):0] s_status_depth_commit,
    output wire                   s_status_overflow,
    output wire                   s_status_bad_frame,
    output wire                   s_status_good_frame,
    output wire [$clog2(DEPTH):0] m_status_depth,
    output wire [$clog2(DEPTH):0] m_status_depth_commit,
    output wire                   m_status_overflow,
    output wire                   m_status_bad_frame,
    output wire                   m_status_good_frame
);

    localparam ADDR_WIDTH = $clog2(DEPTH);
    localparam DEPTH_MASK = DEPTH - 1;
    localparam DEPTH_PLUS_1 = DEPTH + 1;
    localparam DEPTH_PLUS_1_WIDTH = $clog2(DEPTH_PLUS_1);

    // Total data width for storage
    localparam TOTAL_DATA_WIDTH = DATA_WIDTH + 
                                  (KEEP_ENABLE ? KEEP_WIDTH : 0) + 
                                  (LAST_ENABLE ? 1 : 0) + 
                                  (ID_ENABLE ? ID_WIDTH : 0) + 
                                  (DEST_ENABLE ? DEST_WIDTH : 0) + 
                                  (USER_ENABLE ? USER_WIDTH : 0);

    // Internal signals
    wire [ADDR_WIDTH:0] s_wr_ptr;
    wire [ADDR_WIDTH:0] m_rd_ptr;
    wire [ADDR_WIDTH:0] s_wr_ptr_sync;
    wire [ADDR_WIDTH:0] m_rd_ptr_sync;

    wire [ADDR_WIDTH:0] s_wr_ptr_sync_1;
    wire [ADDR_WIDTH:0] s_wr_ptr_sync_2;
    wire [ADDR_WIDTH:0] m_rd_ptr_sync_1;
    wire [ADDR_WIDTH:0] m_rd_ptr_sync_2;

    wire [ADDR_WIDTH:0] s_wr_ptr_m;
    wire [ADDR_WIDTH:0] m_rd_ptr_s;

    wire [ADDR_WIDTH:0] s_depth;
    wire [ADDR_WIDTH:0] m_depth;

    wire s_full;
    wire m_empty;
    wire s_wr_en;
    wire m_rd_en;

    wire [TOTAL_DATA_WIDTH-1:0] s_wr_data;
    wire [TOTAL_DATA_WIDTH-1:0] m_rd_data;

    wire s_pause_active;
    wire m_pause_active;

    wire s_overflow_pulse;
    wire m_overflow_pulse;
    wire s_bad_frame_pulse;
    wire m_bad_frame_pulse;
    wire s_good_frame_pulse;
    wire m_good_frame_pulse;

    wire s_overflow_flag;
    wire m_overflow_flag;
    wire s_bad_frame_flag;
    wire m_bad_frame_flag;
    wire s_good_frame_flag;
    wire m_good_frame_flag;

    wire [ADDR_WIDTH:0] s_depth_commit;
    wire [ADDR_WIDTH:0] m_depth_commit;

    // RAM storage
    reg [TOTAL_DATA_WIDTH-1:0] ram [0:DEPTH-1];

    // Write pointer (source clock domain)
    reg [ADDR_WIDTH:0] s_wr_ptr_reg;

    // Read pointer (destination clock domain)
    reg [ADDR_WIDTH:0] m_rd_ptr_reg;

    // Synchronization of write pointer to destination domain
    reg [ADDR_WIDTH:0] s_wr_ptr_sync_1_reg;
    reg [ADDR_WIDTH:0] s_wr_ptr_sync_2_reg;

    // Synchronization of read pointer to source domain
    reg [ADDR_WIDTH:0] m_rd_ptr_sync_1_reg;
    reg [ADDR_WIDTH:0] m_rd_ptr_sync_2_reg;

    // Status flags
    reg s_overflow_flag_reg;
    reg m_overflow_flag_reg;
    reg s_bad_frame_flag_reg;
    reg m_bad_frame_flag_reg;
    reg s_good_frame_flag_reg;
    reg m_good_frame_flag_reg;

    // Commit depth tracking
    reg [ADDR_WIDTH:0] s_depth_commit_reg;
    reg [ADDR_WIDTH:0] m_depth_commit_reg;

    // Pause logic
    reg s_pause_ack_reg;
    reg m_pause_ack_reg;

    // Frame tracking for source domain
    reg s_in_frame;
    reg s_frame_overflow;

    // Frame tracking for destination domain
    reg m_in_frame;
    reg m_frame_overflow;

    // Assign write pointer
    assign s_wr_ptr = s_wr_ptr_reg;
    assign m_rd_ptr = m_rd_ptr_reg;

    // Synchronized pointers
    assign s_wr_ptr_sync = s_wr_ptr_sync_2_reg;
    assign m_rd_ptr_sync = m_rd_ptr_sync_2_reg;

    // Cross-domain pointers
    assign s_wr_ptr_m = s_wr_ptr_sync;
    assign m_rd_ptr_s = m_rd_ptr_sync;

    // Depth calculations
    assign s_depth = s_wr_ptr - m_rd_ptr_s;
    assign m_depth = s_wr_ptr_m - m_rd_ptr;

    // Full and empty conditions
    assign s_full = (s_depth >= DEPTH);
    assign m_empty = (m_depth == 0);

    // Write enable
    assign s_wr_en = s_axis_tvalid && s_axis_tready && !s_pause_active;

    // Read enable
    assign m_rd_en = m_axis_tvalid && m_axis_tready && !m_pause_active;

    // Pause active signals
    assign s_pause_active = PAUSE_ENABLE ? s_pause_req : 1'b0;
    assign m_pause_active = PAUSE_ENABLE ? m_pause_req : 1'b0;

    // Overflow detection
    assign s_overflow_pulse = s_axis_tvalid && s_full && !DROP_WHEN_FULL && !MARK_WHEN_FULL;
    assign m_overflow_pulse = 1'b0; // Overflow is detected on write side

    // Bad frame detection
    wire s_bad_frame_pulse_wire;
    wire m_bad_frame_pulse_wire;

    // Good frame detection
    wire s_good_frame_pulse_wire;
    wire m_good_frame_pulse_wire;

    // Frame logic
    wire s_frame_end = s_axis_tvalid && s_axis_tready && s_axis_tlast && !s_pause_active;
    wire m_frame_end = m_axis_tvalid && m_axis_tready && m_axis_tlast && !m_pause_active;

    // Bad frame condition: frame exceeds DEPTH
    wire s_frame_oversize = FRAME_FIFO && s_in_frame && s_full && !s_axis_tlast;

    // Assign bad frame pulses
    assign s_bad_frame_pulse = (DROP_BAD_FRAME || DROP_OVERSIZE_FRAME) ? s_frame_oversize : 1'b0;
    assign m_bad_frame_pulse = 1'b0;

    // Good frame pulse
    assign s_good_frame_pulse = s_frame_end && !s_frame_oversize;
    assign m_good_frame_pulse = m_frame_end;

    // Tready logic
    wire s_tready_base;
    assign s_tready_base = !s_full || DROP_WHEN_FULL || MARK_WHEN_FULL;

    assign s_axis_tready = PAUSE_ENABLE ? (s_tready_base && !s_pause_req) : s_tready_base;

    // M valid logic
    assign m_axis_tvalid = !m_empty && !m_pause_active;

    // Data packing for write
    wire [TOTAL_DATA_WIDTH-1:0] packed_wr_data;

    // Unpacking for read
    wire [DATA_WIDTH-1:0] unpacked_tdata;
    wire [KEEP_WIDTH-1:0] unpacked_tkeep;
    wire unpacked_tlast;
    wire [ID_WIDTH-1:0] unpacked_tid;
    wire [DEST_WIDTH-1:0] unpacked_tdest;
    wire [USER_WIDTH-1:0] unpacked_tuser;

    // Pack data
    generate
        if (KEEP_ENABLE && LAST_ENABLE && ID_ENABLE && DEST_ENABLE && USER_ENABLE) begin
            assign packed_wr_data = {s_axis_tdata, s_axis_tkeep, s_axis_tlast, s_axis_tid, s_axis_tdest, s_axis_tuser};
            assign unpacked_tdata = m_rd_data[TOTAL_DATA_WIDTH-1:DATA_WIDTH];
            assign unpacked_tkeep = m_rd_data[DATA_WIDTH+KEEP_WIDTH-1:DATA_WIDTH];
            assign unpacked_tlast = m_rd_data[DATA_WIDTH+KEEP_WIDTH];
            assign unpacked_tid = m_rd_data[DATA_WIDTH+KEEP_WIDTH+1:DATA_WIDTH+KEEP_WIDTH+ID_WIDTH];
            assign unpacked_tdest = m_rd_data[DATA_WIDTH+KEEP_WIDTH+ID_WIDTH+1:DATA_WIDTH+KEEP_WIDTH+ID_WIDTH+DEST_WIDTH];
            assign unpacked_tuser = m_rd_data[DATA_WIDTH+KEEP_WIDTH+ID_WIDTH+DEST_WIDTH:0];
        end
        else if (KEEP_ENABLE && LAST_ENABLE && ID_ENABLE && DEST_ENABLE) begin
            assign packed_wr_data = {s_axis_tdata, s_axis_tkeep, s_axis_tlast, s_axis_tid, s_axis_tdest};
            assign unpacked_tdata = m_rd_data[TOTAL_DATA_WIDTH-1:DATA_WIDTH];
            assign unpacked_tkeep = m_rd_data[DATA_WIDTH+KEEP_WIDTH-1:DATA_WIDTH];
            assign unpacked_tlast = m_rd_data[DATA_WIDTH+KEEP_WIDTH];
            assign unpacked_tid = m_rd_data[DATA_WIDTH+KEEP_WIDTH+1:DATA_WIDTH+KEEP_WIDTH+ID_WIDTH];
            assign unpacked_tdest = m_rd_data[DATA_WIDTH+KEEP_WIDTH+ID_WIDTH:0];
            assign unpacked_tuser = {USER_WIDTH{1'b0}};
        end
        else if (KEEP_ENABLE && LAST_ENABLE && ID_ENABLE) begin
