            assign unpacked_tdata = m_rd_data[TOTAL_DATA_WIDTH-1:DATA_WIDTH];
            assign unpacked_tkeep = m_rd_data[DATA_WIDTH+KEEP_WIDTH-1:DATA_WIDTH];
            assign unpacked_tlast = m_rd_data[DATA_WIDTH+KEEP_WIDTH];
            assign unpacked_tid = m_rd_data[DATA_WIDTH+KEEP_WIDTH+1:DATA_WIDTH+KEEP_WIDTH+ID_WIDTH];
            assign unpacked_tdest = {DEST_WIDTH{1'b0}};
            assign unpacked_tuser = {USER_WIDTH{1'b0}};
        end
